/* ────────────────────────────────────────────────────────────── audit log ── */

/**
 * A believable history for a record that has been around a while.
 *
 * Built backwards from `updatedAt`: the most recent entry is the last edit,
 * and the first is always the creation. Every seed record therefore has a
 * trail that ENDS where its `updatedAt` says it should — the audit tab and the
 * summary card cannot disagree.
 */
export function seedAudit(
  r: () => number,
  opts: { createdAt: string; updatedAt: string; noun: string; fields: string[] }
): AuditEvent[] {
  const out: AuditEvent[] = [];
  const n = intBetween(r, 1, 5);
  let cursor = new Date(opts.updatedAt).getTime();

  for (let i = 0; i < n; i += 1) {
    const fields = someOf(r, opts.fields, 3);
    out.push({
      id: `au-${Math.floor(r() * 1e9).toString(36)}`,
      at: new Date(cursor).toISOString(),
      by: pickFrom(r, ACTORS),
      action: i === 0 ? "Updated" : pickFrom(r, ["Updated", "Status changed", "Document uploaded"] as const),
      changes: fields.map((f) => `${f} changed`),
    });
    cursor -= intBetween(r, 2, 60) * 86_400_000;
    if (cursor <= new Date(opts.createdAt).getTime()) break;
  }

  out.push({
    id: `au-${Math.floor(r() * 1e9).toString(36)}`,
    at: new Date(opts.createdAt).toISOString(),
    by: pickFrom(r, STAFF),
    action: "Created",
    changes: [`${opts.noun} record created`],
  });

  return out;
}

/** Files a record of this kind would plausibly be carrying. */
export function seedAttachments(
  r: () => number,
  names: readonly string[],
  max = 3
): Attachment[] {
  const n = intBetween(r, 0, max);
  const chosen = n === 0 ? [] : someOf(r, names, n);
  return chosen.map((name, i) => ({
    id: `at-${Math.floor(r() * 1e9).toString(36)}-${i}`,
    name,
    kind: name.endsWith(".xlsx") ? "xlsx" : name.endsWith(".png") ? "png" : "pdf",
    sizeKb: intBetween(r, 40, 4800),
    uploadedAt: dateOffset(-intBetween(r, 10, 700)),
    uploadedBy: pickFrom(r, STAFF),
    expiresOn: /certificate|insurance|w-9|permit|inspection/i.test(name)
      ? dateOffset(intBetween(r, -120, 500))
      : null,
  }));
}

/*
  The Directory's form VOCABULARY — the field and section shapes the four
  entities declare, and the contract about when a form complains.

  THE FORM ITSELF IS THE RECORD SHEET. The DS's interaction for a record is the
  side sheet (`RecordSheet`, as `CustomerSheet` uses it): the record IS the
  form, and there is no separate full-page editor. This module therefore
  describes the fields; `DirectoryRecordSheet` renders them.

  The contract is identical on all four entities:

    · NOTHING IS RED UNTIL YOU HAVE LEFT IT. Validating a required field while
      it is still empty and still focused tells somebody they have made a
      mistake before they have had a chance to make one. A field validates on
      blur, and after the first failed save it validates as you type — because
      by then you know it is wrong and want to see it go green.

    · A FAILED SAVE NEVER LOSES ANYTHING. The form keeps every character,
      scrolls to the first bad field and focuses it. The one thing worse than
      an error is an error that also empties the form.

    · CANCEL WITH CHANGES ASKS FIRST. Without changes it just leaves — a
      confirmation nobody needs is a confirmation everybody learns to dismiss
      without reading, which is how the ones that matter stop working.

  REQUIRED IS MARKED, OPTIONAL IS MARKED. Marking only one of the two makes the
  reader infer the other, and on a form this long with this many genuinely
  optional fields the inference is wrong often enough to matter.
*/

export type FieldKind =
  | "text"
  | "email"
  | "tel"
  | "number"
  | "money"
  | "date"
  | "select"
  /**
   * A select you can type into, and — with `allowCreate` — extend. For a field
   * whose set is known but not closed: a contact's role, a tag, a category
   * somebody invented this morning. A fixed list there pushes the real answer
   * into a notes field where nothing can filter on it.
   */
  | "combobox"
  | "switch"
  | "checkbox"
  | "textarea";

export interface FormFieldDef<T> {
  key: string;
  label: string;
  kind: FieldKind;
  required?: boolean;
  /** Helper text under the control. */
  description?: string;
  placeholder?: string;
  options?: readonly string[];
  /** `combobox` only — offer what was typed when it matches no option. */
  allowCreate?: boolean;
  /** Full width in the section grid — instructions, notes, addresses. */
  wide?: boolean;
  /** Reads the value out of the draft. */
  get: (draft: T) => string | number | boolean | null;
  /** Writes it back. Returns the next draft; never mutates. */
  set: (draft: T, value: string | number | boolean | null) => T;
  /** Field-level rule. Return the message, or null when it is fine. */
  validate?: (draft: T) => string | null;
  /** Hidden when this returns false — dependent fields, e.g. a limit that only
   *  applies to approved accounts. */
  visible?: (draft: T) => boolean;
}

export interface FormSectionDef<T> {
  key: string;
  title: string;
  /**
   * The section's "why", shown ON DEMAND behind the ⓘ by its title
   * (`SheetSectionNote`) — never as a paragraph under it. Named `note`, not
   * `description`, so the difference from a field's always-visible helper
   * text is in the code and the microcopy check can tell them apart.
   */
  note?: string;
  fields: FormFieldDef<T>[];
}

/*
  The cross-references between the four Directory entities.

  WHY A SEPARATE FILE. `orders.ts` imports from `vendors.ts` (the picker needs
  carriers) and `directory.ts` imports from `orders.ts` (products and ship-tos
  are the ones orders actually name). A vendor pointing at a product would close
  that loop, so the links are made HERE, by a module that imports everything and
  is imported by nothing except the screens.

  It runs once, on first import, and mutates the seed records in place. That is
  the same thing a backend join would do, minus the join.
*/
import {
  BROKER_CUSTOMERS,
  BROKER_PRODUCTS,
  RENTAL_ASSETS,
  SHIP_TO_LOCATIONS,
  type BrokerCustomer,
  type BrokerProduct,
  type RentalAsset,
} from "./directory";
import { BROKER_ORDERS } from "./orders";
import {
  VENDORS,
  setAssignedOrderCounts,
  type Vendor,
} from "./vendors";
import { intBetween, rng, someOf } from "./directoryCore";

let linked = false;

function link(): void {
  if (linked) return;
  linked = true;

  /* ── which products a vendor can actually haul ──────────────────────────
     Derived from the vendor's BUSINESS LINES rather than drawn at random: a
     carrier that runs Bulk Fuel and nothing else must not turn up as capable
     of a lube drum, because the order sheet filters on exactly this. */
  const byCategory = {
    Fuel: BROKER_PRODUCTS.filter((p) => p.category === "Fuel").map((p) => p.id),
    DEF: BROKER_PRODUCTS.filter((p) => p.category === "DEF").map((p) => p.id),
    Lubricant: BROKER_PRODUCTS.filter((p) => p.category === "Lubricant").map((p) => p.id),
    Additive: BROKER_PRODUCTS.filter((p) => p.category === "Additive").map((p) => p.id),
    Service: BROKER_PRODUCTS.filter((p) => p.category === "Service").map((p) => p.id),
  };

  VENDORS.forEach((v, i) => {
    const r = rng(21_000 + i);
    const pool = new Set<string>();
    if (v.businessLines.includes("Bulk Fuel")) byCategory.Fuel.forEach((id) => pool.add(id));
    if (v.businessLines.includes("DEF")) byCategory.DEF.forEach((id) => pool.add(id));
    if (v.businessLines.includes("Packaged Lubes")) {
      byCategory.Lubricant.forEach((id) => pool.add(id));
      byCategory.Additive.forEach((id) => pool.add(id));
    }
    if (v.businessLines.includes("Emergency Response")) byCategory.Service.forEach((id) => pool.add(id));

    /* Not everything in the pool — a carrier runs a subset of what its line
       covers, and "supports 6 of 17 fuels" is the fact the picker needs. */
    const all = [...pool];
    v.supportedProductIds =
      all.length === 0 ? [] : someOf(r, all, Math.max(2, Math.round(all.length * 0.6)));
    v.preferredCustomerIds =
      r() < 0.3 ? someOf(r, BROKER_CUSTOMERS.map((c) => c.id), 4) : [];
  });

  /* ── which vendors can supply a product — the same fact, read the other way ── */
  const supports = new Map<string, string[]>();
  VENDORS.forEach((v) => {
    v.supportedProductIds.forEach((pid) => {
      const list = supports.get(pid) ?? [];
      list.push(v.id);
      supports.set(pid, list);
    });
  });
  BROKER_PRODUCTS.forEach((p, i) => {
    const r = rng(22_000 + i);
    p.availableVendorIds = supports.get(p.id) ?? [];
    p.defaultVendorIds =
      p.availableVendorIds.length > 0 ? someOf(r, p.availableVendorIds, 2) : [];
  });

  /* ── the vendor a customer prefers, and the vendor servicing an asset ── */
  BROKER_CUSTOMERS.forEach((c, i) => {
    const r = rng(23_000 + i);
    if (r() < 0.35) {
      const eligible = VENDORS.filter((v) => v.active && v.serviceStates.length > 0);
      c.preferredVendorId = eligible[intBetween(r, 0, eligible.length - 1)]?.id ?? null;
    }
  });

  RENTAL_ASSETS.forEach((a, i) => {
    const r = rng(24_000 + i);
    if (r() < 0.55) {
      const movers = VENDORS.filter((v) => v.assetHandlingCapable && v.active);
      a.assignedVendorId = movers[intBetween(r, 0, movers.length - 1)]?.id ?? null;
    }
  });

  /* ── live order counts, so the Vendors list can carry a real column ── */
  const LIVE = new Set(["Quoting", "Assigned", "Completed", "Review", "Verified", "Partially Synced"]);
  const counts: Record<string, number> = {};
  BROKER_ORDERS.forEach((o) => {
    if (!LIVE.has(o.status)) return;
    const ids = new Set<string>([
      ...(o.vendorId ? [o.vendorId] : []),
      ...o.acceptedVendorIds,
      ...o.invitedVendorIds,
    ]);
    ids.forEach((id) => {
      counts[id] = (counts[id] ?? 0) + 1;
    });
  });
  setAssignedOrderCounts(counts);
}

link();

/* ── lookups the screens use ─────────────────────────────────────────────── */

export const customerById = (id: string | null): BrokerCustomer | null =>
  id ? BROKER_CUSTOMERS.find((c) => c.id === id) ?? null : null;

export const productById = (id: string | null): BrokerProduct | null =>
  id ? BROKER_PRODUCTS.find((p) => p.id === id) ?? null : null;

export const assetById = (id: string | null): RentalAsset | null =>
  id ? RENTAL_ASSETS.find((a) => a.id === id) ?? null : null;

export const shipToById = (id: string | null) =>
  id ? SHIP_TO_LOCATIONS.find((s) => s.id === id) ?? null : null;

/** Orders placed by this account, newest first. Drives the detail page's tab. */
export const ordersForCustomer = (name: string) =>
  BROKER_ORDERS.filter((o) => o.customer.title === name);

/** Everything this vendor is on, live or done. */
export const ordersForVendor = (vendorId: string) =>
  BROKER_ORDERS.filter(
    (o) =>
      o.vendorId === vendorId ||
      o.acceptedVendorIds.includes(vendorId) ||
      o.invitedVendorIds.includes(vendorId)
  );

/** Orders whose lines name this product. */
export const ordersForProduct = (productName: string) =>
  BROKER_ORDERS.filter((o) => o.lines.some((l) => l.product === productName));

/** Orders whose lines name this asset. */
export const ordersForAsset = (assetName: string) =>
  BROKER_ORDERS.filter((o) => o.lines.some((l) => l.asset === assetName));

/** Assets out at this account right now. */
export const assetsForCustomer = (customerId: string): RentalAsset[] =>
  RENTAL_ASSETS.filter((a) => a.customerId === customerId);

/** Ship-tos belonging to this account. */
export const shipTosForCustomer = (customerId: string) =>
  SHIP_TO_LOCATIONS.filter((s) => s.customerId === customerId);

/** Vendors that can supply this product AND are assignable today. */
export const vendorsForProduct = (p: BrokerProduct): Vendor[] =>
  VENDORS.filter((v) => p.availableVendorIds.includes(v.id));

import { DATE_FMT, MONEY, dateKeyOf, relativeLabel, startOfDay } from "../data";
