/**
 * Command item — Figma "Command / Item" (430:20061). Beyond the raw cmdk item,
 * this surfaces the component's documented properties as ergonomic props:
 *   - `icon`        → leading slot (the "Icon" variant; an INSTANCE_SWAP in Figma)
 *   - `selected`    → trailing ✓ (the "Selected" variant)
 *   - `shortcut`    → trailing shortcut text (the "Shortcut Text" property)
 *   - `showShortcut`→ toggles the shortcut (the "Show Shortcut" BOOLEAN, default true)
 * The Default/Hover/Disabled "State" variant is left to cmdk (it drives
 * `data-[selected]`/`data-[disabled]`), so it isn't a manual prop. Passing only
 * `children` keeps the plain shadcn behaviour — every existing call still works.
 *
 * ⚠️ DO NOT hand-roll this row layout. Setting ANY of `icon` / `selected` /
 * `shortcut` switches the item into structured mode, which wraps `children` in a
 * single `flex-1 truncate` span. Flex children you pass inside `children` then
 * collapse onto one truncated line, silently — no error, just a broken row that
 * costs real debugging time. Use the slots:
 *
 * ```tsx
 * <CommandItem icon={<Truck />} shortcut="12 orders">Carrier name</CommandItem>
 * ```
 *
 * `selected` renders a trailing ✓, which marks *the* chosen row — correct for
 * SINGLE-select. For multi-select use `MultiSelectList` (checkbox rows): a ✓ on
 * a multi-select list reads as "this is the current value", and with nothing yet
 * chosen the list is indistinguishable from a single-select one.
 */
function CommandItem({
  className,
  children,
  icon,
  selected,
  shortcut,
  showShortcut = true,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Item> & {
  icon?: React.ReactNode;
  selected?: boolean;
  shortcut?: React.ReactNode;
  showShortcut?: boolean;
}) {
  // Only compose the structured layout when an FP prop is supplied; otherwise
  // render children verbatim (backward-compatible with bare cmdk usage).
  const structured = icon != null || selected != null || shortcut != null;
  return (
    <CommandPrimitive.Item
      data-slot="command-item"
      className={cn(
        "relative flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50 data-[selected=true]:bg-accent data-[selected=true]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground",
        className
      )}
      {...props}
    >
      {structured ? (
        <>
          {icon}
          <span className="flex-1 truncate">{children}</span>
          {selected && <CheckIcon className="ml-auto size-4 text-foreground" />}
          {shortcut != null && showShortcut && (
            <CommandShortcut>{shortcut}</CommandShortcut>
          )}
        </>
      ) : (
        children
      )}
    </CommandPrimitive.Item>
  );
}

/**
 * Right-aligned meta slot in a `CommandItem`.
 *
 * `variant` exists because this slot has two jobs. `keycap` is the wide-tracked
 * treatment that suits `⌘K`; `meta` is plain, for the counts, dates and hints
 * that are just as natural on the right of a row and that wide tracking makes
 * look broken. `meta` is the default — wide tracking is the special case, so it
 * should be the one you opt into.
 */
function CommandShortcut({
  className,
  variant = "meta",
  ...props
}: React.ComponentProps<"span"> & { variant?: "meta" | "keycap" }) {
  return (
    <span
      data-slot="command-shortcut"
      data-variant={variant}
      className={cn(
        "ml-auto text-xs text-muted-foreground",
        variant === "keycap" && "tracking-widest",
        className
      )}
      {...props}
    />
  );
}

export {
  Command,
  CommandInput,
  CommandList,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandShortcut,
  CommandSeparator,
};

import * as React from "react";
import { HoverCard as HoverCardPrimitive } from "radix-ui";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

function HoverCard({
  ...props
}: React.ComponentProps<typeof HoverCardPrimitive.Root>) {
  return <HoverCardPrimitive.Root data-slot="hover-card" {...props} />;
}

/**
 * Trigger States — Figma "Hover Card / Trigger" (216:3085). The `link` variant
 * bakes the documented states so call sites don't hand-roll them:
 *   Default → plain · Hover → underline · Focus → ring · Disabled → dimmed.
 * Omit `variant` (or pass `asChild`) for the bare pass-through used when the
 * trigger is a custom element.
 */
const hoverCardTriggerVariants = cva(
  "inline-flex w-fit cursor-pointer items-center rounded-sm font-medium text-foreground underline-offset-4 outline-none transition-colors hover:underline focus-visible:ring-2 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50",
  {
    variants: { variant: { link: "" } },
  }
);

function HoverCardTrigger({
  className,
  variant,
  children,
  asChild,
  ...props
}: React.ComponentProps<typeof HoverCardPrimitive.Trigger> &
  VariantProps<typeof hoverCardTriggerVariants>) {
  // A variant renders its own focusable <button>; without one, pass through
  // (preserving the existing `asChild` API for custom trigger elements).
  if (variant) {
    return (
      <HoverCardPrimitive.Trigger data-slot="hover-card-trigger" asChild>
        <button
          className={cn(hoverCardTriggerVariants({ variant }), className)}
          {...(props as React.ComponentProps<"button">)}
          type="button"
        >
          {children}
        </button>
      </HoverCardPrimitive.Trigger>
    );
  }
  return (
    <HoverCardPrimitive.Trigger
      data-slot="hover-card-trigger"
      className={className}
      asChild={asChild}
      {...props}
    >
      {children}
    </HoverCardPrimitive.Trigger>
  );
}

function HoverCardContent({
  className,
  align = "center",
  sideOffset = 4,
  ...props
}: React.ComponentProps<typeof HoverCardPrimitive.Content>) {
  return (
    <HoverCardPrimitive.Portal data-slot="hover-card-portal">
      <HoverCardPrimitive.Content
        data-slot="hover-card-content"
        align={align}
        sideOffset={sideOffset}
        className={cn(
          "z-50 w-64 origin-(--radix-hover-card-content-transform-origin) rounded-md border border-border bg-popover p-4 text-popover-foreground shadow-md outline-hidden data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95",
          className
        )}
        {...props}
      />
    </HoverCardPrimitive.Portal>
  );
}

export {
  HoverCard,
  HoverCardTrigger,
  HoverCardContent,
  hoverCardTriggerVariants,
};

import * as React from "react"

import { cn } from "@/lib/utils"

/*
  A FIELD STARTS WITH A CAPITAL — except where a capital would be wrong.

  `autoCapitalize` is the standards mechanism for it, and it is honest in a way
  a CSS transform is not: it changes what the SOFT KEYBOARD offers, so the
  value that gets stored is the value the reader saw. `text-transform:
  capitalize` would show one thing and save another, and `::first-letter` does
  not apply to an `<input>` at all.

  IT DOES NOTHING ON A DESKTOP KEYBOARD, deliberately — nothing here rewrites
  what somebody typed. A form that wants the first letter normalised on the way
  out does it at the form layer, where the rule can see the FIELD's meaning;
  see `DirectoryRecordSheet`.

  THE EXCEPTIONS ARE THE POINT. An email, a URL and a password are
  case-carrying strings where a capitalised first letter is either wrong or a
  failed login, and a numeric field has no letters to capitalise. Those get
  `none`, and a caller can still override any of it.
*/
const NEVER_CAPITALISE = ["email", "url", "password", "number", "tel"];

function Input({
  className,
  type,
  autoCapitalize,
  inputMode,
  ...props
}: React.ComponentProps<"input">) {
  const numeric = inputMode === "numeric" || inputMode === "decimal";
  return (
    <input
      type={type}
      inputMode={inputMode}
      autoCapitalize={
        autoCapitalize ??
        (numeric || (type && NEVER_CAPITALISE.includes(type)) ? "none" : "sentences")
      }
      data-slot="input"
      className={cn(
        "h-9 w-full min-w-0 rounded-md border border-input bg-fp-surface-1b px-3 py-1 text-base transition-[color,box-shadow] outline-none selection:bg-primary selection:text-primary-foreground file:inline-flex file:h-7 file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground placeholder:text-muted-foreground disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 md:text-sm dark:bg-fp-field-fill",
        "focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/50",
        "aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40",
        className
      )}
      {...props}
    />
  )
}

export { Input }

import * as React from "react";

import { cn } from "@/lib/utils";
import { HoverCard, HoverCardContent, HoverCardTrigger } from "@/components/ui/hover-card";

/*
  THE PILL — the DS's chip and badge (Pavan, 2026-10-09). Trialled on the
  Sales Orders table after the Lovable reference, approved, and promoted here
  as the default for every status, tag, flag and "+N" in Unified View.

  ONE RECIPE, every pill: fully rounded, 28px tall, 12px side padding, 12px
  regular text, no border, a faint tint of the hue behind text in that hue.
  `docs/ds/ui/2-rules.md` §11b.

  COLOUR IS BY KIND (the five kinds of §10b) unless a module lets the user
  choose one — then `color` takes the DS lane palette over the kind.
*/

/** What kind of state a pill says — §10b. The application binds its statuses
 *  to these; the DS never names a status. */
export type PillKind = "neutral" | "info" | "caution" | "success" | "critical";

const KIND_PILL: Record<PillKind, string> = {
  neutral: "bg-muted text-muted-foreground",
  info: "bg-fp-banner-accent-info/10 text-fp-banner-accent-info",
  caution: "bg-fp-banner-accent-caution/10 text-fp-banner-accent-caution",
  success: "bg-status-success/10 text-status-success",
  critical: "bg-status-failed/10 text-status-failed",
};

/*
  A CHOSEN COLOUR (Pavan, 2026-10-09) — for tags whose colour is picked by the
  user (Sales stages, order types) rather than set by meaning. The DS lane
  palette: a faint tint of the hue behind text mixed from that hue and the
  body ink, so it reads in both themes.
*/
export type PillColor =
  | "grey" | "blue" | "yellow" | "green" | "cyan"
  | "purple" | "violet" | "pink" | "orange" | "red";

export const PILL_COLORS: { value: PillColor; label: string }[] = [
  { value: "grey", label: "Grey" },
  { value: "blue", label: "Blue" },
  { value: "yellow", label: "Yellow" },
  { value: "green", label: "Green" },
  { value: "cyan", label: "Cyan" },
  { value: "purple", label: "Purple" },
  { value: "violet", label: "Violet" },
  { value: "pink", label: "Pink" },
  { value: "orange", label: "Orange" },
  { value: "red", label: "Red" },
];

const COLOR_PILL: Record<PillColor, string> = {
  grey: "bg-fp-lane-grey/12 text-[color-mix(in_oklab,var(--color-fp-lane-grey)_70%,var(--foreground))]",
  blue: "bg-fp-lane-blue/12 text-[color-mix(in_oklab,var(--color-fp-lane-blue)_70%,var(--foreground))]",
  yellow: "bg-fp-lane-yellow/18 text-[color-mix(in_oklab,var(--color-fp-lane-yellow)_55%,var(--foreground))]",
  green: "bg-fp-lane-green/12 text-[color-mix(in_oklab,var(--color-fp-lane-green)_60%,var(--foreground))]",
  cyan: "bg-fp-lane-cyan/12 text-[color-mix(in_oklab,var(--color-fp-lane-cyan)_60%,var(--foreground))]",
  purple: "bg-fp-lane-purple/12 text-[color-mix(in_oklab,var(--color-fp-lane-purple)_70%,var(--foreground))]",
  /* THE ACCENT (2026-10-16) — the violet pill is the accent's soft wash and ink. */
  violet: "bg-accent-violet-soft text-accent-violet-ink",
  pink: "bg-fp-lane-pink/12 text-[color-mix(in_oklab,var(--color-fp-lane-pink)_70%,var(--foreground))]",
  orange: "bg-fp-lane-orange/15 text-[color-mix(in_oklab,var(--color-fp-lane-orange)_60%,var(--foreground))]",
  red: "bg-fp-lane-red/12 text-[color-mix(in_oklab,var(--color-fp-lane-red)_70%,var(--foreground))]",
};

/** The shape every pill shares — exported so a chip drawn by another
 *  component (`StatusChip`) cannot drift from it. */
export const PILL_SHAPE =
  "inline-flex h-7 max-w-full shrink-0 items-center rounded-full px-3 text-xs font-normal whitespace-nowrap";

/** The colour classes for a kind, or for a chosen colour over it. */
export function pillColorClass(kind: PillKind = "neutral", color?: PillColor | null) {
  return color ? COLOR_PILL[color] : KIND_PILL[kind];
}

export interface PillProps
  extends Omit<React.HTMLAttributes<HTMLSpanElement>, "children" | "className" | "color"> {
  kind?: PillKind;
  /** A chosen colour, over the kind's. */
  color?: PillColor | null;
  className?: string;
  children: React.ReactNode;
}

export function Pill({ kind = "neutral", color, className, children, ...rest }: PillProps) {
  return (
    <span
      data-slot="pill"
      data-kind={color ? undefined : kind}
      {...rest}
      className={cn(PILL_SHAPE, pillColorClass(kind, color), className)}
    >
      <span className="truncate">{children}</span>
    </span>
  );
}

/**
 * THE FIRST VALUE AS A PILL, the rest behind a "+N" pill that lists them on
 * hover — products and tags on a row.
 */
export function PillList({
  values,
  label,
  kind = "neutral",
}: {
  values: string[];
  label: string;
  kind?: PillKind;
}) {
  if (values.length === 0) return <span className="text-sm text-muted-foreground">—</span>;
  const [first, ...rest] = values;
  return (
    <span className="flex min-w-0 items-center gap-1.5">
      <Pill kind={kind} className="min-w-0 shrink">
        {first}
      </Pill>
      {rest.length > 0 && (
        <HoverCard openDelay={80}>
          <HoverCardTrigger asChild>
            <button
              type="button"
              aria-label={`Show all ${values.length} ${label}`}
              className="shrink-0 rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
            >
              <Pill kind={kind} className="tabular-nums">
                +{rest.length}
              </Pill>
            </button>
          </HoverCardTrigger>
          <HoverCardContent align="start" className="w-auto max-w-72 p-2">
            <span className="flex flex-wrap gap-1.5">
              {values.map((v) => (
                <Pill key={v} kind={kind}>
                  {v}
                </Pill>
              ))}
            </span>
          </HoverCardContent>
        </HoverCard>
      )}
    </span>
  );
}

